INSERT OR IGNORE INTO dishes VALUES('46128ffc-4c52-46d4-bd76-1e29176a7e29','4081f2dd-c06e-458f-945b-b868c0259691','ac247f38-5015-470b-a380-2fa7f4479d24','The Traditional Breakfast','The Classics',NULL,'Two fresh cage-free eggs any style with your choice of bacon, smoked ham, savory chicken sausage patties, turkey or pork sausage links. Served with whole grain artisan toast, all-natural house preserves and fresh, seasoned potatoes. Substitute Udi''s Gluten Free toast at no additional charge.','[{"tag":"egg","source":"stated"},{"tag":"gluten","source":"stated"},{"tag":"meat","source":"stated"}]');
