INSERT OR IGNORE INTO dishes VALUES('ec63026a-3e42-4622-b864-191318937565','4081f2dd-c06e-458f-945b-b868c0259691','ac247f38-5015-470b-a380-2fa7f4479d24','Biscuits & Turkey Sausage Gravy with Eggs','The Classics',NULL,'One large freshly baked buttermilk biscuit split in two with homestyle turkey sausage gravy, two cage-free eggs any style and a side of fresh, seasoned potatoes.','[{"tag":"poultry","source":"stated"},{"tag":"egg","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
