INSERT OR IGNORE INTO dishes VALUES('950b6b78-20b9-45d4-b50a-b359af675b8f','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Bianca Pizza','Artisan Pizzas',12.949999999999999289,'An elegant white pizza featuring a garlic-infused base, topped with creamy mozzarella and tangy feta, savory sausage, and fresh florets of broccoli.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('3adc765e-acea-45a5-ae26-566ae1489d62','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','The Queen Pizza','Artisan Pizzas',12.949999999999999289,'A royal tribute to Italian tradition. Our classic tomato base is adorned with fresh, creamy mozzarella, fragrant basil, a whisper of garlic, and a kiss of fresh oregano and Parmesan.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('f5036327-98d7-4d43-82c8-ff86e47d1c6b','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Homecoming Pizza','Artisan Pizzas',10.949999999999999289,'The familiar taste of home, elevated. A comforting classic with our signature tomato sauce, melted mozzarella, and savory, crisp-edged pepperoni.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('d1a0a326-4422-46ed-a984-17c8f8dc10b3','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','The Brown''s Pizza','Artisan Pizzas',12.949999999999999289,'A Mediterranean dream. A vibrant pesto base layered with mozzarella, sun-ripened tomatoes, feta cheese, garlic, tender spinach, and rich Kalamata olives.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('9107ebd9-bc4a-4f18-b139-a1a631b40d5e','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Henry''s Pizza','Artisan Pizzas',12.949999999999999289,'A daring and delicious dance of sweet and heat. This pizza features fresh mozzarella and aromatic basil, all brought to life with a drizzle of sweet balsamic glaze and a surprising kick of hot honey.','[{"tag":"dairy","source":"stated"},{"tag":"spicy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('b0288d89-7663-416b-8a54-ee6705c8caa2','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Buffalo''s Pizza','Artisan Pizzas',12.949999999999999289,'All the flavor of your favorite wings on a pizza! A zesty buffalo & ranch base topped with mozzarella, tender chicken, and savory bacon.','[{"tag":"dairy","source":"stated"},{"tag":"poultry","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"spicy","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('aca6bc33-c607-4f11-b0a0-c694894ee1a0','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','GiarDino Pizza','Artisan Pizzas',12.949999999999999289,'A fresh and vibrant trip through the garden. Our tomato base is topped with mozzarella, spinach, tomatoes, onions, bell peppers, artichoke hearts, and mushrooms.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('4d1af8fe-820f-47e9-9f8a-fc7d037498ca','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','La Toscana Pizza','Artisan Pizzas',12.949999999999999289,'A taste of the Tuscan countryside. Fragrant pesto provides the base for mozzarella, spinach, sweet grilled onions, feta, garlic, and a finishing drizzle of rich balsamic glaze.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('544395f9-7494-4958-adc8-dde03351463f','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','La Fiesta Pizza','Artisan Pizzas',12.949999999999999289,'A celebration of bold flavors! A smoky BBQ sauce base with melted cheddar and mozzarella cheeses, topped with tender, seasoned chicken.','[{"tag":"dairy","source":"stated"},{"tag":"poultry","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('dc23f50b-9f65-4e1b-8ab9-9787df883fce','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Philly''s Pizza','Artisan Pizzas',12.949999999999999289,'A taste of the City of Brotherly Love. A creamy ranch base topped with mozzarella, tender steak, and a medley of sweet bell peppers and onions.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"beef","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('6f1a36c4-2a1c-4b71-a2d8-587caf218d58','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Supremo Pizza','Artisan Pizzas',12.949999999999999289,'The ultimate pizza experience. A flavor explosion of pepperoni, bacon, sausage, bell peppers, onions, and green olives over our classic tomato sauce and mozzarella.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('a04fccb9-d0dc-461b-a957-eb16f0f4aafb','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Aloha Pizza','Artisan Pizzas',12.949999999999999289,'A sweet and savory escape to the islands. Our signature tomato sauce and mozzarella, topped with savory ham and sweet, juicy pineapple.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('20a65fb5-2570-4e87-9f7b-26f7b71a0832','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Dino''s Pizza','Artisan Pizzas',12.949999999999999289,'Named for the man himself, this is a celebration of Italian flavor. A creamy ricotta base with mozzarella, savory sausage, garlic, spinach, onions, and a final, shimmering drizzle of extra virgin olive oil.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('a0fb8c25-b0d6-403d-9533-71caefdf48c4','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Meatlovers Pizza','Artisan Pizzas',12.949999999999999289,'A hearty feast for the senses. A savory masterpiece loaded with pepperoni, bacon, sausage, and ham over our classic tomato sauce and melted mozzarella.','[{"tag":"dairy","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"gluten","source":"inferred"}]');
