INSERT OR IGNORE INTO dishes VALUES('171dc4ff-a223-4548-812b-c6697658fec6','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Build Your Own Bowl','Bowls',12.949999999999999289,'Build your own bowl with 1 base, 4 fresh vegetables, 1 protein of your choice, and finish it with 2 garnishes.','[]');
INSERT OR IGNORE INTO dishes VALUES('e2875f84-4c25-43de-ab30-b6054ded2968','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','TexMex Bowl','Bowls',12.949999999999999289,'A hearty bowl with fluffy rice and tender chicken, topped with fresh pico de gallo, sweet corn, creamy guacamole, melted cheese, and cool sour cream, finished with crunchy chips and a drizzle of smoky chipotle sauce.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"}]');
INSERT OR IGNORE INTO dishes VALUES('4971858a-9846-4fbb-a803-6ba3fcca9fbf','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Mediterranean Bowl','Bowls',12.949999999999999289,'A fresh and vibrant bowl with fluffy rice and tender chicken, layered with crisp lettuce, creamy coleslaw, juicy tomatoes, and crunchy cucumbers, topped with tangy feta cheese and a cool drizzle of tzatziki sauce.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"}]');
