INSERT OR IGNORE INTO dishes VALUES('dc7cf54e-0e43-4523-b515-bba5476a885c','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Chicken Bacon Ranch Calzone','Calzones',12.999999999999999999,'Chicken Bacon Ranch Calzone is packed with tender chicken, crispy bacon, and melted cheese, folded in our house-made dough and baked golden brown, finished with a drizzle of creamy ranch.','[{"tag":"poultry","source":"stated"},{"tag":"meat","source":"stated"},{"tag":"pork","source":"inferred"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('582c38f2-ebe9-4f7c-b93d-ede131257f01','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Buffalo Chicken Calzone','Calzones',12.999999999999999999,'A bold calzone stuffed with tender chicken, melted cheese, and our spicy Buffalo sauce, folded in house-made dough, baked golden, and served with a side of cool ranch.','[{"tag":"poultry","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"spicy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('32097e35-4a92-4b21-9227-719e473e8172','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Veggie Calzone','Calzones',12.999999999999999999,'A hearty calzone filled with fresh vegetables, melted cheese, and our signature house-made dough, baked to golden perfection and served hot from the oven.','[{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('e7b0da2c-b2ea-40ab-bf94-08831651591e','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Pepperoni Calzone','Calzones',10.0,'A classic calzone loaded with zesty pepperoni and melted cheese, wrapped in our house-made dough and baked golden brown to perfection.','[{"tag":"meat","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('94bcf0b2-1895-4d59-9289-3dd9eb21266f','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Philly Steak Calzone','Calzones',12.999999999999999999,'A savory calzone stuffed with thinly sliced steak, sautéed peppers and onions, and melted cheese, wrapped in our house-made dough and baked golden brown.','[{"tag":"meat","source":"stated"},{"tag":"beef","source":"inferred"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('3b4136a3-c4d1-4f6e-ac11-c7ce22c2120a','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Meatball Calzone','Calzones',12.999999999999999999,'A hearty calzone filled with Italian-style meatballs, rich marinara sauce, and melted mozzarella cheese, wrapped in our house-made dough and baked golden brown.','[{"tag":"meat","source":"stated"},{"tag":"dairy","source":"stated"},{"tag":"gluten","source":"inferred"}]');
INSERT OR IGNORE INTO dishes VALUES('8206fcfe-0d63-41ac-b9ea-546099a52bf2','449f9d95-add9-4fb2-8a5f-811965fefab3','0bd7f18c-6376-4940-9067-8de5c9d7e646','Build your own Wrap','Wraps',9.8499999999999996447,'Select at least 1: Falafel, Hummus, Tzatziki, Green Salad, Cucumbers, Tomatoes, Romaine, Mixed Greens.','[{"tag":"gluten","source":"inferred"}]');
