INSERT OR IGNORE INTO dishes VALUES('e8e9e48a-955e-4aba-b1da-af0688507ce2','b9cf1ea9-7203-40d2-8e12-909928c21a93','d256119f-e831-4a42-a3bc-1812e2ebd745','Ginger Lemongrass Noodle Soup','HEARTY SOUP and SANDWICH',15.949999999999999289,'Fresh ginger and lemongrass infused tofu in a house vegetarian broth rice noodles with baby greens, bean sprouts, caramelized onions, Thai basil, cilantro and lime. **Let us know if you are eating at home, we''ll separate the noodles from the broth for a better eating experience.','[{"tag":"soy","source":"inferred"}]');
