INSERT OR IGNORE INTO reviews VALUES('6a51511f-2844-44e6-ad4b-9cea01014463','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT2pkUGQxZHZTM0p0Ym1oalZuRmZRa1ZKV2xwbVVHYxAB','google','French onion soup is fantastic! Great menu, but the food was okay.  It was busy brunch time so maybe that was the reason it was just okay.',4,'2026-07-30','2026-11-12T02:01:07.283Z');
INSERT OR IGNORE INTO reviews VALUES('937f2a51-dee1-4804-ace3-4e8983d07443','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT25sVVRWSTFkbms1VVhCUFV6Rm9UVlpyUVVzMGVtYxAB','google','Fish tacos are very delicious!!',4,'2026-07-30','2026-11-12T02:01:07.283Z');
