INSERT OR IGNORE INTO reviews VALUES('536ed7b9-54a8-4063-95a2-5db3d5d53c45','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT2tGNmRrbHlYMkZDTFVSNloxVkJibEZ3WTNWWWEwRRAB','google','Really good burger. Big tap beer selection 👌!',5,'2026-07-27','2026-11-12T02:01:07.283Z');
