INSERT OR IGNORE INTO reviews VALUES('58953322-95d4-409f-b38d-e1e7119b769c','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT2pjM1duQjBMVkp2YkMxdFlWRkRhWEF6TjJaUlEzYxAB','google','Great food.  Good prices.  Try the hummus.   Delicious!',4,'2026-06-30','2026-11-12T02:01:07.283Z');
INSERT OR IGNORE INTO reviews VALUES('1d53cc4e-5a14-4559-86f7-c29e1a523b91','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT25WeU4zSmtZbEI2Y2tsamNFaDRkVlZPVGxaRGEwRRAB','google','Conveniently located and easy to get to, this place checks all the right boxes. The food is fantastic — fresh, flavorful, and consistently well done. But the real standout? Their happy hour. Incredible deals that make a great experience even better. Whether you’re stopping in after work or meeting up with friends, Sedona Tap House delivers every time. Highly recommend!',5,'2026-06-23','2026-11-12T02:01:07.283Z');
