INSERT OR IGNORE INTO reviews VALUES('927cb5c8-c369-4b48-a101-4a79085f05e7','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT25sWmJ6Tm5SSFJNYm0xaVdVdzVVMHgyV21SVWEzYxAB','google','Tried Sedona Taphouse while visiting the area. Absolutely can’t say enough good things about this restaurant. My husband and MIL had the scallops and I had the Devils Pass pasta. Everyone’s dishes were amazing! I can’t wait to eat here again!',5,'2025-07-21','2026-11-12T02:01:07.283Z');
