INSERT OR IGNORE INTO reviews VALUES('ae413d01-8ae5-4aad-b5b8-ab5e9f8cf260','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT25Bd01tMWtVMmcwVUZRNVRubHpTblpPTFhCT2IzYxAB','google','The food was outstanding! Delicious appetizers! Great beer selection, too. Loved the atmosphere. Plenty of parking. Clean bathrooms.  Thanks, Annie, for taking care of us!',5,'2025-07-18','2026-11-12T02:01:07.283Z');
INSERT OR IGNORE INTO reviews VALUES('65781ee9-a643-4e0a-9a06-730a86ee3c85','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT201QmJIVmhhSEpLUlRZMVVXNXhRVkJGY1dSeVJXYxAB','google','Met up with some friends here, loved the ambiance.  They had a huge selection of beers.  We were pleased with our beers, ciders and delicious food.  Our waitress Annie was very attentive and friendly.  Nice outside seating.  Clean restrooms, easy accessibility and plenty of parking.',5,'2025-07-16','2026-11-12T02:01:07.283Z');
INSERT OR IGNORE INTO reviews VALUES('128c1bd5-ea73-4c50-8330-2322d41a86c0','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT2tJdFl6WnlZbEZaU21odWNqSkpTMDVFV0RGNWRFRRAB','google','Nice atmosphere, great food, and great service.',5,'2025-07-13','2026-11-12T02:01:07.283Z');
