INSERT OR IGNORE INTO reviews VALUES('8face823-7500-4c54-80fa-068a409ee18a','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT201a1dHSldUMk5qT1dKMFlqRnVUV3MyYzE4elJrRRAB','google','We absolutely loved this place. Service, food, and beer selection 👌 even DELICIOUS NA options. 10/10',5,'2025-06-22','2026-11-12T02:01:07.283Z');
INSERT OR IGNORE INTO reviews VALUES('364cfc19-8b39-461c-94e1-08d2a538db7a','1dfeda34-1e99-4a0b-866c-0213b052024b','google:Ci9DQUlRQUNvZENodHljRjlvT2pKQmNHNHpWRlV4VlRGVWNqbGhPVFV5VG5KT1VsRRAB','google','Five stars for everything. This is a neighborhood restaurant with plenty of parking. Huge selection of beers on tap and in bottles. The Desert Fire Jalapeños deserve an award. Everything else we ordered (burger, salad, flatbread) were delicious. Highly recommended.',5,'2025-06-22','2026-11-12T02:01:07.283Z');
