INSERT OR IGNORE INTO reviews VALUES('b15563cf-481d-41d9-9614-ed3f28d7bfe0','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:Ci9DQUlRQUNvZENodHljRjlvT25CamREQm5NVGxITlU1ZlJYbHpaVWRKTVRoa2RYYxAB','google','I asked for 3 al pastor and I guess they ran out and mixed in asada with my “Al pastor tacos”. Funny.',1,'2026-05-17','2026-11-12T02:03:12.175Z');
INSERT OR IGNORE INTO reviews VALUES('5c49be3e-3459-4729-9f6d-d60347909e7a','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:Ci9DQUlRQUNvZENodHljRjlvT2tWSlFrSjNkVXRvZVZwUVpVeE5VME0yZFZFNFpYYxAB','google','Coming from a big ol’ Texas boy, El Puerto is unmatched across all categories. I eat here every week and am met with the same friendly faces, remembering both me and my order. The food without fail makes me a happy fella and fills me up every time. Not to mention, it’s the best value Mexican food in the city.',5,'2026-05-07','2026-11-12T02:03:12.175Z');
INSERT OR IGNORE INTO reviews VALUES('1d800964-a96a-4e25-9b26-b2eb4ba89257','6d1d6697-8aaa-4257-b26c-25f8b9173150','google:Ci9DQUlRQUNvZENodHljRjlvT2tsQ1gzcFFZVUZLY2tkVkxVRktSSFp4WkcxQ1puYxAB','google','Best chori pollo',5,'2026-05-07','2026-11-12T02:03:12.175Z');
