INSERT OR IGNORE INTO reviews VALUES('1dedea7a-5dc1-408b-957c-736a04f9d168','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:ChdDSUhNMG9nS0VJQ0FnSURRNGFMWm13RRAB','google','This is just what I remembered from graduate school, only this one is closer to campus.  They still don''t take plastic and everything is served in styrofoam.  The prices are about the same as before despite the recession.  The decor is literally that of someone''s kitchen with a cash-only register.  Felt like a new-age lemonade stand - for dumplings.',4,'2016-07-09','2026-11-12T02:04:59.005Z');
