INSERT OR IGNORE INTO reviews VALUES('89d594d3-d99e-44e5-9b33-25712148c167','ef2cbaed-4345-4637-9d65-58d6be2a8f6e','google:Ci9DQUlRQUNvZENodHljRjlvT2pabU0waEdaSFZwT0ZCcWQxaDVkRlp3Wkd4b2FYYxAB','google','Very cute and chill place to eat, very affordable for the quantity and quality of food. The small wanton soup is pretty big I couldn’t even finish it all! Everything was so tasty and the owners are so sweet.',5,'2025-10-18','2026-11-12T02:04:59.005Z');
