INSERT OR IGNORE INTO reviews VALUES('26ee60fe-994d-4331-901a-4c5ed00fb9b4','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:Ci9DQUlRQUNvZENodHljRjlvT205ME1tUmZiRTUyVFZGTllUTkpVV2xuYlRKVmNYYxAB','google','awesome time here always! staff are so kind and welcoming and great vibes atmosphere! LOVE GLOZET!!!! support the local charlottesville community🌈',5,'2026-07-30','2026-11-12T02:12:50.528Z');
