INSERT OR IGNORE INTO reviews VALUES('8c677b81-0b96-44f4-820f-5786d1671086','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChdDSUhNMG9nS0VJQ0FnSUNlMEpxbjdnRRAB','google','Pizza was bland',2,'2022-09-03','2026-11-12T02:12:50.528Z');
INSERT OR IGNORE INTO reviews VALUES('e605013a-9a2e-4ca3-b9bc-14b976dfab05','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSUR1eF9UbVd3EAE','google','Great pizza but pricey with a large pizza at $25+ . Good for offering vegan cheese options for Calzones and pizzas. Nice selection of draft beers and one local draft cider (boldrock IPA - one of my faves).',4,'2022-08-31','2026-11-12T02:12:50.528Z');
