INSERT OR IGNORE INTO reviews VALUES('220f9c00-4827-4f79-a55d-eb99d1e7a697','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChZDSUhNMG9nS0VJQ0FnSUNha0tLN2F3EAE','google','A bit pricey but really good overall I got the calzone and it was fantastic',5,'2021-07-21','2026-11-12T02:12:50.528Z');
INSERT OR IGNORE INTO reviews VALUES('6529273f-618c-440a-a399-29f1b2031ba4','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChdDSUhNMG9nS0VJQ0FnSURxdjVqMzl3RRAB','google','Best pizza in Charlottesville. We tried the Capone, emerald and fun guy. Each pizza was unique in taste and really good. Can’t wait to be back to try more.',5,'2021-07-20','2026-11-12T02:12:50.528Z');
