INSERT OR IGNORE INTO reviews VALUES('cf47dfc8-d068-4042-969f-8c1b04980744','1adbf072-d1f2-473a-b4f5-3b2b76d96cd3','google:ChRDSUhNMG9nS0VJQ0FnSURRc3I1bBAB','google','Always a huge fan of Crozet pizza and the Cville location is just as good.  We don’t go to cville without getting Crozet pizza and always bring another one home.',5,'2018-07-10','2026-11-12T02:12:50.528Z');
