INSERT OR IGNORE INTO reviews VALUES('e24e310a-054a-4170-977f-1bc0d540f702','304e70e5-b297-4251-8c96-46e58e96d6d4','google:ChZDSUhNMG9nS0VJQ0FnSURLanJlNERBEAE','google','Lots of pretty lady''s',4,'2021-05-11','2026-11-12T02:12:50.919Z');
INSERT OR IGNORE INTO reviews VALUES('8ff9f4f3-56e9-4710-8e50-aa3c188b4765','304e70e5-b297-4251-8c96-46e58e96d6d4','google:ChZDSUhNMG9nS0VJQ0FnSUNLNXEzUFlnEAE','google','Just wanted a quick bite after a long day. Went to the front and whoever was outside checking ids went inside to clean off a tabke. Keep in mind, we were only a party of 2 people and the first in line. Anyways, he comes back outside, looking like he was about to give us a table but then his "buddies" rounded the corner and suddenly our table was gone and given to them and we were told it would be a 45 minute wait.<br><br>Unprofessional and rude to say the least.',1,'2021-04-04','2026-11-12T02:12:50.919Z');
