INSERT OR IGNORE INTO reviews VALUES('4401ebec-0ae8-435a-bca6-3bbe03b43fe1','476dfdb1-6f8c-4e52-950d-172696b8659a','google:Ci9DQUlRQUNvZENodHljRjlvT2tOMWFWZERTalJLYnpoR1ptWTFSMlJhVTFOdWRFRRAB','google','I really hate this place because of the music they play..... late at night..... when I''m trying to sleep.',1,'2025-09-18','2026-11-12T02:14:23.246Z');
