INSERT OR IGNORE INTO reviews VALUES('75110f85-c2e0-43ef-9ef2-84df1c6a0caa','476dfdb1-6f8c-4e52-950d-172696b8659a','google:ChdDSUhNMG9nS0VJQ0FnTURRNTVQUXpnRRAB','google','I''ve been here on and off in the last 10 years and they never disappoint with my Old Fashioned.',5,'2025-03-15','2026-11-12T02:14:23.246Z');
