INSERT OR IGNORE INTO reviews VALUES('69675cf0-9843-4e4a-97c9-fac324a553c8','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT2t4VGRXZFRZMnA2WVhSRk1WRjRVM1JoVjBWcFgyYxAB','google','Me and my friends only had about 15 dollars on us and we got one shawarma to share between the five of us when on elf the workers saw us all sharing one shawarma she gave us  a free loaded bowl and free sodas we love you guys so much Otto’s workers are the best people to exist we love you!  💗',5,'2026-04-19','2026-11-12T02:17:02.463Z');
