INSERT OR IGNORE INTO reviews VALUES('1e48483d-1c8d-4b7c-ba05-b48f95c34336','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT25aWlMyUXRWbEUxYmxBMFIzaGhTbDlLZDJkb2JtYxAB','google','Otto is the perfect spot for a quick and delicious lunch! The falafel pitas were delicious and packed with flavor. The staff were so welcoming and nice. Will be stopping by whenever we’re back in Charlottesville!',5,'2026-04-02','2026-11-12T02:17:02.463Z');
