INSERT OR IGNORE INTO reviews VALUES('fdd78bf6-e7bc-45a8-b0b0-a3d7d4ac956f','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT21GT2JHSkljMjlwVERsTGNsVm5RamRSV0ZKV09VRRAB','google','I fell in love as soon as I walked in the door. As someone who loves culture, I could feel it instantly here. I got recommended an amazing bowl and chocolate baklava(first time having it and it was amazing!)<br><br>Had a great convo with the host and enjoyed the food. 10/10 recommend',5,'2026-02-24','2026-11-12T02:17:02.463Z');
