INSERT OR IGNORE INTO reviews VALUES('a932b58d-90bc-41ce-8cda-e97e4f3526e5','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT2tONE9IRkVNRmROYWpsSGNWWnNiRU5tYlZoT1JFRRAB','google','The best restaurant ever there was two guys take my order and they was really kind. I always eat from here but first time I want do a review because is the best place I go to the best customer service and best food.',5,'2026-02-10','2026-11-12T02:17:02.463Z');
INSERT OR IGNORE INTO reviews VALUES('d0c4e7c7-8788-4054-8378-7e991d07c519','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT2xodlEweFljbE5IWW1KcE0wdFhTWGRyZUU5R2VsRRAB','google','Unmatched when it comes to taste, good service, and stellar menu. You cannot order something bad here, every last thing is perfection. Get the Ottobun Pita first, and tip the staff handsomely!',5,'2026-01-28','2026-11-12T02:17:02.463Z');
