INSERT OR IGNORE INTO reviews VALUES('14c97ee9-277f-42cb-8f1a-9f73f5b7c786','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT21FMFgwWjBla1V4U0ZoZk0yWmFWbUpCY1cxRldrRRAB','google','Excellent food! It was fresh and flavorful. The multi colored plates added to the vibrancy of the place. Lots of interesting artwork on the walls, another feast for the eyes. A good variety of canned soda/juices as well; try the sour cherry juice. Overall, we were very happy with our choice.',5,'2026-01-18','2026-11-12T02:17:02.463Z');
INSERT OR IGNORE INTO reviews VALUES('f7804a4b-ce2f-4894-abc5-2d3492f759d8','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT201R1QyZEhhVzU1VTJRNU9VbGhRVGxYUW1kM1JrRRAB','google','Great fresh food deserts and service .',5,'2026-01-18','2026-11-12T02:17:02.463Z');
