INSERT OR IGNORE INTO reviews VALUES('ca4fc841-c963-468a-8a7c-a77eb233a8cd','076db689-5c85-4d4d-ad85-217cc2db8172','google:Ci9DQUlRQUNvZENodHljRjlvT2tSdE5rUllSVzgyTlRkeVRVbExjVGRPWW1sUmFGRRAB','google','A true gem of cville! Worth the trip for Turkish coffee alone. The cuisine is not only delicious but also a healthier alternative to many other meals dining out.',5,'2026-01-04','2026-11-12T02:17:02.463Z');
