INSERT OR IGNORE INTO reviews VALUES('03946593-8498-4772-a933-0eb4a56436d0','5e8a057b-5ad8-433d-96f3-6b5cceea1484','google:ChZDSUhNMG9nS0VJQ0FnSURKcXVHZE1REAE','google','We''ve been patronizing ''Rev Soup'' (as we refer to it) for many years (as of summer 2023), and it''s been pretty consistent in offering delicious, nutritious food at modest prices.',5,'2023-07-14','2026-11-12T02:18:40.230Z');
