INSERT OR IGNORE INTO reviews VALUES('1628ca7a-e49c-4e2e-ba26-f131b4adb69b','5e8a057b-5ad8-433d-96f3-6b5cceea1484','google:ChZDSUhNMG9nS0VJQ0FnSURxdjd5ZVR3EAE','google','It''s been 5 years since I frequented here but I can only imagine it''s as tasty today.',5,'2021-07-20','2026-11-12T02:18:40.230Z');
