INSERT OR IGNORE INTO reviews VALUES('9194d850-7ddc-481d-87ed-242eff49eb64','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT2xGTVQzTndORFpQVUY5SFJYQnZkRWh2UzNWSE1tYxAB','google','Absolutely delicious, got dinner for two and everything tasted great. Recommend this place to all',5,'2026-09-22','2026-11-12T02:18:41.615Z');
INSERT OR IGNORE INTO reviews VALUES('2847ad90-976a-4783-a5fa-178b4a56c661','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT25rMGRHbzNaMUJoVW1wTGMyTnhaM0pCWjFWM09XYxAB','google','Delicious food and friendly service! Would recommend',5,'2026-09-10','2026-11-12T02:18:41.615Z');
