INSERT OR IGNORE INTO reviews VALUES('20692b0e-f797-4460-8e86-7ba636fcc659','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT21sVE4xcEpkblUwUVVSTFZHTnhlVzVZTFdaRmJHYxAB','google','This restaurant is a great addition to the downtown mall area. They have amazing traditional Afghani food. Their friendly staff help you from the moment you walk in. The food you get is always fresh they serve enough to share so bring your appetite friends and family.',5,'2026-05-15','2026-11-12T02:18:41.615Z');
INSERT OR IGNORE INTO reviews VALUES('c87b31bc-b023-4ca8-a02e-9aa54374017a','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT2paak1XRkhURmhJY1d3dGJtUmZjVlJUUjBwMlVYYxAB','google','Incredible food',5,'2026-05-13','2026-11-12T02:18:41.615Z');
