INSERT OR IGNORE INTO reviews VALUES('d3cbd499-1d19-4260-bbf4-8b7830882758','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT21GQ1gyaFpla3R0ZDFCTlZsOVFObTE0YTBGMmVsRRAB','google','We loved the food and atmosphere. It’s authentic and also amazing service',5,'2026-03-28','2026-11-12T02:18:41.615Z');
INSERT OR IGNORE INTO reviews VALUES('35e027b4-96f6-4db3-90af-bd65413c671e','eef4e05e-1a04-4212-a410-53c232168f7f','google:Ci9DQUlRQUNvZENodHljRjlvT25KRWNEbFhjbVpWV2pJd1ptMXlVemhUVjNkdlluYxAB','google','My family and I very much enjoyed our meal here. The server was very nice and helped us pick the best options. All the meat was very well seasoned and the rice was cooked to perfection. I would come here every day!Definitely the best Afghan restaurant ever!',5,'2026-03-28','2026-11-12T02:18:41.615Z');
